// Translations for the four result pages, the login page, the privacy notice
// (/privacy) and the catch-all.
//
// Kept separate from strings.js purely for size: that file covers the chrome and
// the four data-entry steps, this one covers the result pages and the pages
// outside the journey (/login, /privacy, the catch-all). Both
// are merged per language in strings.js, so a key here is looked up exactly the
// same way and falls back to English the same way.
//
// SCOPE: only labels, headings and our own sentences live here. The prose inside
// a result — advisory recommendations, business observations, the risk reason,
// scheme descriptions and match reasons — is generated or held by the backend and
// is translated through its own code, in backendStrings.js and schemeStrings.js.
// It used to be English on this page regardless of language; that gap is closed.
//
// The one thing that stays English here is an enum-to-label map's INPUT. A level,
// status or risk value arrives as an English enum because it is load-bearing in
// Python, and each result page turns it into plain language at render through a
// map (LEVEL_KEYS, STATUS_KEYS, RISK_KEYS). Add a value to the enum and you must
// add it to the map and to the eight dicts below in the same edit — an unmapped
// value falls back to the title-cased enum, which is legible but is English.
//
// Machine-assisted, and the money strings need a native-speaker pass.

