  'privacy.sentTitle': 'क्या भेजा जाता है',
  'privacy.sentLead': 'आख़िरी चरण पर {button} बटन दबाने पर सिर्फ़ ये जवाब भेजे जाते हैं:',
  'privacy.sentConsent': 'इनके साथ यह जानकारी भी जाती है कि आपने सहमति दी: इस सूचना का संस्करण, आप किस भाषा में पढ़ रहे थे, समय, और अगर आपसे उम्र के बारे में पूछा गया था तो आपका जवाब।',
  'privacy.localTitle': 'क्या सिर्फ़ इसी डिवाइस पर रहता है',
  'privacy.localText': 'ये कभी नहीं भेजे जाते: आपका नाम, आपके काम का नाम, आपका गाँव या कस्बा, आप कहाँ बेचते हैं, और आपके ग्राहक कौन हैं। ये इसी ब्राउज़र टैब में रहते हैं और आपकी रिपोर्ट में छपते हैं। {startover} बटन दबाने पर ये मिट जाते हैं, और टैब बंद करने पर भी आम तौर पर मिट जाते हैं। आपकी बोली भी कभी नहीं भेजी जाती। यह ब्राउज़र अगली बार के लिए आपकी बोली, अक्षर का आकार और रंग याद रखता है। यह आपकी भाषा भी याद रखता है, जो आपकी सहमति के साथ भेजी जाती है।',
  'privacy.whyTitle': 'क्यों',
  'privacy.whyText': 'आपके जवाब इसलिए भेजे जाते हैं ताकि आपका परिणाम निकाला जा सके: आँकड़े ठीक बैठते हैं या नहीं, कौन-सी योजनाएँ और इलाके के आँकड़े दिखाने हैं, और आगे क्या करना है। जैसा नीचे बताया गया है, आपके जवाबों से बना एक कोड भी इस जाँच के रिकॉर्ड के रूप में रखा जाता है।',
  'privacy.keptTitle': 'क्या रखा जाता है',
  'privacy.keptText': 'यह सॉफ़्टवेयर आपके भेजे गए जवाब सेव नहीं करता। हर जाँच के लिए यह एक रिकॉर्ड लिखता है: समय, आपकी सहमति की जानकारी, आपके जवाबों से बना एक कोड, और तकनीकी बातें, जैसे जाँच ठीक से हुई या नहीं। एक जैसे जवाबों से एक जैसा कोड बनता है, लेकिन रिकॉर्ड में आपके जवाब खुद नहीं होते। अगर कोई जवाब छूटा हो या गलत हो और इस वजह से जाँच न हो पाए, तो रिकॉर्ड में सिर्फ़ समय और वे तकनीकी बातें होती हैं।',
  'privacy.keptDays': 'ये रिकॉर्ड {fiduciary} के पास {days} दिन तक रखे जाते हैं।',
  'privacy.keptAsk': 'ये रिकॉर्ड कितने दिन रखे जाते हैं, यह जानने के लिए यहाँ पूछें: {contact}',
  'privacy.keptUnknown': 'इस कॉपी में यह नहीं बताया गया है कि ये रिकॉर्ड कितने दिन रखे जाते हैं।',
  'privacy.hostLogs': 'इस सेवा को चलाने वाले कंप्यूटर भी अपने रिकॉर्ड रख सकते हैं, जिनमें आपके डिवाइस का इंटरनेट पता हो सकता है। ज़्यादातर वेबसाइटों पर ऐसा होता है।',
  'privacy.choicesTitle': 'आप क्या कर सकते हैं',
  'privacy.choiceStop': 'आगे बढ़ना ज़रूरी नहीं है। जब तक आप सहमति वाले बॉक्स पर निशान लगाकर {button} बटन नहीं दबाते, कुछ भी नहीं भेजा जाता।',
  'privacy.choiceStartOver': 'इस टैब से अपने जवाब मिटाने के लिए ऊपर {startover} बटन दबाएँ। जो पहले ही भेजा जा चुका है, उस पर इसका कोई असर नहीं होता।',
  'privacy.choiceRights': 'अपनी सहमति वापस लेने के लिए, या जो भेजा गया है उसे देखने, ठीक करवाने या मिटवाने के लिए, या शिकायत करने के लिए यहाँ संपर्क करें: {contact}',
  'privacy.choiceNoContact': 'इस कॉपी में अपनी सहमति वापस लेने, या जो भेजा गया है उसे देखने, ठीक करवाने या मिटवाने के लिए कोई संपर्क नहीं दिया गया है। जिस व्यक्ति या संस्था ने आपको यह लिंक दिया है, उनसे पूछें।',
  'privacy.grievanceLink': '{fiduciary} से शिकायत करें',
  'privacy.board': '13 मई 2027 से, अगर आपकी शिकायत के जवाब से आप संतुष्ट नहीं हैं, तो आप भारत के डेटा संरक्षण बोर्ड (Data Protection Board of India) से भी शिकायत कर सकते हैं।',
  'privacy.age': '18 साल या उससे ज़्यादा उम्र के लोग ही इसे अपने आप इस्तेमाल कर सकते हैं। इससे कम उम्र के व्यक्ति के साथ माता-पिता या अभिभावक होने चाहिए, जो इसके लिए सहमत हों।',
  'privacy.version': 'इस सूचना का संस्करण: {version}',

  'talk.title': 'बोलकर या लिखकर जवाब भरें',
  'talk.optional': 'वैकल्पिक शॉर्टकट',
  'talk.subtitle': 'कुछ वाक्यों में बताइए कि आपका काम क्या है, आपको कितने पैसे चाहिए और आप कहाँ रहते हैं। हम आपकी बात से जवाब ढूँढ़ते हैं, और फ़ॉर्म में जाने से पहले हर जवाब आप खुद जाँचते हैं।',
