  'sch.eyebrow': 'ప్రభుత్వ సహాయం',
  'sch.title': 'మీకు సహాయపడే పథకాలు',
  'sch.subtitle': 'మీ పని రకం, మీ రాష్ట్రం, మీ వ్యాపారం గ్రామంలోనా నగరంలోనా అనే దాని ఆధారంగా వీటిని ఎంచుకున్నాం. ఇది జాబితాలో ఎందుకు ఉందో, దరఖాస్తు ముందు ఏమి చూడాలో తెలుసుకోడానికి పథకం తెరవండి.',
