  'sch.noneText': 'మేము చూసే పథకాలు మీరు ఎంచుకున్న పనిని కలిగి లేవు. ఇది తిరస్కరణ కాదు — మా సమాచారంతో సరిపోలికను నిర్ధారించలేకపోయాం అని మాత్రమే.',
  'sch.noneCovered': 'మేము చూసే పథకాలు వీటికి సహాయం చేస్తాయి: దుకాణం మరియు కొనుగోలు అమ్మకం, వస్తువులు తయారు చేయడం, సేవ పని, తినే సామాను తయారు చేయడం, కుట్టు పని, చేతి పని, వ్యవసాయం, పాల పని, కోళ్ల పెంపకం, తేనెటీగల పెంపకం మరియు రోడ్డు మీద అమ్మకం. మీ పని వీటిలో ఏదైనా దానికి దగ్గరగా ఉంటే, వెనక్కి వెళ్లి దాన్నే ఎంచుకోండి.',
