  'ad.riskLowHouseholdOver': 'ప్రతి నెలా మిగిలే డబ్బుతో అప్పు వాయిదాలు కట్టవచ్చు, కానీ అవి మీ కుటుంబ ఆదాయంలో సగం కంటే ఎక్కువ తీసుకుంటున్నాయి.',
  'ad.riskModDesc': 'కొత్త అప్పు విషయంలో జాగ్రత్తగా ఉండండి, నగదును గమనించండి.',
  'ad.riskHighDesc': 'తీర్చే శక్తి మెరుగయ్యే వరకు కొత్త అప్పు తీసుకోవద్దు.',
  'ad.riskUnknownDesc': 'మరింత అప్పు తీసుకునే ముందు తీర్చే శక్తిని చూడండి.',
  'ad.step1': 'నెలకు ఎంత వస్తోంది, ఎంత పోతోందో మళ్లీ చూడండి.',
  'ad.step2': 'మీ పనికి సరిపోయిన ప్రభుత్వ పథకాలు చూడండి.',
  'ad.step3': 'మీరు ఎంచుకున్న సహాయానికి కావలసిన పత్రాలు సిద్ధంగా ఉంచండి.',
  'ad.step4': 'కొత్త అప్పు తీసుకునే ముందు తీర్చే శక్తిని చూడండి.',

  'rp.eyebrow': 'వ్యాపార నివేదిక',
