  'rp.profile': 'మీ వివరాలు',
  'rp.moneySummary': 'డబ్బు సారాంశం',
  'rp.nextTitle': 'తర్వాత మీరు ఏమి చేయాలి',
  'rp.observations': 'మేము గమనించినది',
  'rp.detailedFigures': 'వివరమైన అంకెలు చూపించు',
  'rp.noScheme': 'ఈ తనిఖీలో ఏ ప్రభుత్వ పథకమూ సరిపోలేదు.',
  'rp.schemeNote': 'జాబితాలో ఉన్నంత మాత్రాన మీరు అర్హులని అర్థం కాదు. ప్రస్తుత నియమాలు, దరఖాస్తు విధానం ఎప్పుడూ ప్రభుత్వ కార్యాలయంలో తనిఖీ చేయండి.',
  'rp.footer': 'ఈ నివేదిక ప్రాథమిక మార్గదర్శనం ఇస్తుంది. పథక అర్హత, రుణ ఆమోదం మరియు ఆదాయం ప్రభుత్వ నియమాలు మరియు మీ పరిస్థితిపై ఆధారపడతాయి.',
  'rp.keepNote': 'ఈ నివేదికలోని లెక్కలు, సలహా మీరు పంపిన జవాబుల నుంచి లెక్కించినవి. మీరు {startover} అనే బటన్‌ను నొక్కే వరకు ఈ ట్యాబ్ మీ జవాబులను, ఈ నివేదికను ఉంచుకుంటుంది, ట్యాబ్ మూసివేస్తే సాధారణంగా అవి తొలగిపోతాయి. ఈ నివేదికను ఉంచుకోవాలంటే, ఇప్పుడే {button} అనే బటన్‌ను నొక్కి దీన్ని ప్రింట్ చేయండి లేదా PDFగా సేవ్ చేయండి.',
