  'ch.householdRbiCovered': 'നിങ്ങൾ പറഞ്ഞ വരുമാനം അനുസരിച്ച്, നിങ്ങളുടെ കുടുംബം വർഷം {income} വരെ സമ്പാദിക്കുന്നു. ഇത്തരം കുടുംബങ്ങൾക്ക്, പുതിയ വായ്പ ഉൾപ്പെടെ കുടുംബത്തിലെ എല്ലാ വായ്പകളുടെയും അടവുകൾ കുടുംബത്തിന്റെ മാസ വരുമാനത്തിന്റെ {limit}%ൽ കൂടുതലായാൽ, RBI നിയന്ത്രിക്കുന്ന വായ്പ സ്ഥാപനം പുതിയ മൈക്രോഫിനാൻസ് വായ്പ നൽകരുതെന്ന് RBI നിയമങ്ങൾ പറയുന്നു.',
  'ch.householdRbiNotCovered': 'നിങ്ങൾ പറഞ്ഞ വരുമാനം അനുസരിച്ച്, നിങ്ങളുടെ കുടുംബം വർഷം {income}-ൽ കൂടുതൽ സമ്പാദിക്കുന്നു. മൈക്രോഫിനാൻസ് വായ്പകൾക്കുള്ള RBI-യുടെ {limit}% പരിധി അത്രവരെ സമ്പാദിക്കുന്ന കുടുംബങ്ങൾക്ക് മാത്രമാണ്, അതുകൊണ്ട് നിങ്ങളുടെ കുടുംബത്തിന് ബാധകമല്ല. മറ്റു വായ്പകൾക്ക് ഓരോ വായ്പ നൽകുന്നവരും സ്വന്തം പരിധി വെക്കുന്നു. എങ്കിലും {limit}% വര ഒരു മുന്നറിയിപ്പായി ഞങ്ങൾ കാണിക്കുന്നു, നിങ്ങളുടെ കുടുംബത്തിനുള്ള നിയമമായിട്ടല്ല.',
