  'sch.subtitle': 'നിങ്ങളുടെ ജോലിയുടെ തരം, സംസ്ഥാനം, സംരംഭം ഗ്രാമത്തിലാണോ നഗരത്തിലാണോ എന്നിവ നോക്കിയാണ് ഇവ തിരഞ്ഞെടുത്തത്. ഇത് എന്തുകൊണ്ട് പട്ടികയിലുണ്ട്, അപേക്ഷിക്കുന്നതിന് മുൻപ് എന്ത് നോക്കണം എന്ന് അറിയാൻ ഒരു പദ്ധതി തുറക്കൂ.',
  'sch.finishTitle': 'ആദ്യം നിങ്ങളുടെ വിവരങ്ങൾ പൂർത്തിയാക്കൂ',
  'sch.finishText': 'ആദ്യം നാലു ഘട്ടങ്ങളും പൂർത്തിയാക്കൂ, അപ്പോൾ നിങ്ങളുടെ ജോലിയും സംസ്ഥാനവും നോക്കിയുള്ള പദ്ധതികൾ കാണിക്കാം.',
  'sch.noneTitle': 'ചേരുന്ന പദ്ധതി ഒന്നും കിട്ടിയില്ല',
  'sch.noneText': 'ഞങ്ങൾ നോക്കുന്ന പദ്ധതികളിൽ നിങ്ങൾ തിരഞ്ഞെടുത്ത ജോലി വരുന്നില്ല. ഇത് ഒരു നിരസിക്കൽ അല്ല — ഞങ്ങളുടെ കൈയിലുള്ള വിവരം വെച്ച് ഒരു ചേർച്ച ഉറപ്പിക്കാൻ കഴിഞ്ഞില്ല എന്നു മാത്രം.',
  'sch.noneCovered': 'ഞങ്ങൾ നോക്കുന്ന പദ്ധതികൾ ഇവയ്ക്കാണ് സഹായം തരുന്നത്: കടയും വാങ്ങലും വിൽപ്പനയും, സാമാനം നിർമ്മാണം, സേവന ജോലി, ഭക്ഷ്യവസ്തു നിർമ്മാണം, തയ്യൽ ജോലി, കൈത്തൊഴിൽ, കൃഷി, പാൽ ജോലി, കോഴി വളർത്തൽ, തേനീച്ച വളർത്തൽ, വഴിയോര വിൽപ്പന. നിങ്ങളുടെ ജോലി ഇതിൽ ഏതിനോടെങ്കിലും അടുത്താണെങ്കിൽ, തിരികെ പോയി അതുതന്നെ തിരഞ്ഞെടുക്കൂ.',
