  'sch.alwaysCheck': 'പുതിയ നിയമങ്ങൾ എപ്പോഴും സർക്കാർ ഓഫീസിൽ നിന്ന് ചോദിച്ച് ഉറപ്പിക്കൂ.',
  'sch.found': '{n} സഹായ വഴികൾ കിട്ടി',
