  'rp.nextTitle': 'ഇനി നിങ്ങൾ എന്ത് ചെയ്യണം',
  'rp.observations': 'ഞങ്ങൾ ശ്രദ്ധിച്ചത്',
  'rp.detailedFigures': 'വിശദമായ കണക്കുകൾ കാണിക്കൂ',
  'rp.noScheme': 'ഈ പരിശോധനയിൽ ഒരു സർക്കാർ പദ്ധതിയും ചേർന്നില്ല.',
  'rp.schemeNote': 'പട്ടികയിൽ ഉണ്ടെന്നതുകൊണ്ട് നിങ്ങൾ യോഗ്യരാണെന്ന് അർത്ഥമില്ല. ഇപ്പോഴുള്ള നിയമങ്ങളും അപേക്ഷിക്കുന്ന വഴിയും എപ്പോഴും സർക്കാർ ഓഫീസിൽ നിന്ന് ഉറപ്പിക്കൂ.',
  'rp.footer': 'ഈ റിപ്പോർട്ട് തുടക്കത്തിലുള്ള വഴികാട്ടൽ തരുന്നു. പദ്ധതിയുടെ അർഹത, വായ്പ അനുവാദം, വരുമാനം ഇവ സർക്കാർ നിയമങ്ങളെയും നിങ്ങളുടെ സ്ഥിതിയെയും ആശ്രയിച്ചിരിക്കും.',
  'rp.keepNote': 'ഈ റിപ്പോർട്ടിലെ കണക്കുകളും ഉപദേശവും നിങ്ങൾ അയച്ച ഉത്തരങ്ങളിൽ നിന്ന് കണക്കാക്കിയതാണ്. നിങ്ങൾ {startover} എന്ന ബട്ടൺ അമർത്തുന്നതുവരെ ഈ ടാബ് നിങ്ങളുടെ ഉത്തരങ്ങളും ഈ റിപ്പോർട്ടും സൂക്ഷിക്കും, ടാബ് അടച്ചാൽ സാധാരണയായി അവ മായും. ഈ റിപ്പോർട്ട് സൂക്ഷിക്കാൻ, ഇപ്പോൾ തന്നെ {button} എന്ന ബട്ടൺ അമർത്തി ഇത് പ്രിന്റ് ചെയ്യുക അല്ലെങ്കിൽ PDF ആയി സേവ് ചെയ്യുക.',
