  'talk.entryText': 'എഴുതുന്നതിനേക്കാൾ സംസാരിക്കാനാണോ ഇഷ്ടം? നിങ്ങളുടെ ഭാഷയിൽ പറയൂ, ഞങ്ങൾ ഫോം നിറയ്ക്കാം, നിങ്ങൾ അത് പരിശോധിക്കുക.',
