  'talk.sendsText': 'നിങ്ങളുടെ ശബ്ദവും വാക്കുകളും Meta നടത്തുന്ന ഒരു AI സേവനത്തിലേക്ക് അയയ്ക്കുന്നു. അത് നിങ്ങളുടെ വാക്കുകൾ എഴുതിയെടുത്ത് അവയിൽ നിന്ന് നിങ്ങളുടെ ഉത്തരങ്ങൾ കണ്ടെത്തുന്നു. ഞങ്ങൾ അവ സൂക്ഷിച്ചു വയ്ക്കുന്നില്ല. Meta അവ സ്വന്തം നിയമങ്ങൾ അനുസരിച്ച് കൈകാര്യം ചെയ്യുന്നു. ഈ സേവനം സൗജന്യ ക്രെഡിറ്റിൽ പ്രവർത്തിക്കുന്നെങ്കിൽ, Meta അവ സ്വന്തം ഉൽപ്പന്നങ്ങൾ മെച്ചപ്പെടുത്താനും ഉപയോഗിച്ചേക്കാം. ദയവായി നിങ്ങളുടെ പേര്, ഫോൺ നമ്പർ, ബാങ്ക് വിവരങ്ങൾ എന്നിവ പറയരുത്.',
  'talk.rulesNote': 'AI കേൾക്കുകയും നിങ്ങളുടെ ഉത്തരങ്ങൾ കണ്ടെത്തുകയും മാത്രമേ ചെയ്യുന്നുള്ളൂ. ഫലം, പദ്ധതികൾ, ഉപദേശം എന്നിവ നിങ്ങൾ ഉത്തരങ്ങൾ സ്വയം എഴുതുമ്പോഴത്തെ പോലെ തന്നെ, മുൻകൂട്ടി നിശ്ചയിച്ച നിയമങ്ങൾ കൊണ്ടാണ് ലഭിക്കുന്നത്.',
