  'ch.householdIncludesNew': 'ಇನ್ನೂ ಬೇಕಾದ ಹಣಕ್ಕಾಗಿ ಸಾಲಕ್ಕೆ ತಿಂಗಳಿಗೆ {amount} ಕೂಡ ಇದರಲ್ಲಿ ಲೆಕ್ಕ ಹಾಕಲಾಗಿದೆ, ವರ್ಷಕ್ಕೆ {rate}% ಬಡ್ಡಿಯಲ್ಲಿ {years} ವರ್ಷಗಳಿಗೆ. ನಿಜವಾದ ಸಾಲಕ್ಕೆ ಇದಕ್ಕಿಂತ ಹೆಚ್ಚು ಅಥವಾ ಕಡಿಮೆ ಖರ್ಚಾಗಬಹುದು.',
  'ch.householdIncludesNewShort': 'ಇನ್ನೂ ಬೇಕಾದ ಹಣಕ್ಕಾಗಿ ಸಾಲಕ್ಕೆ ತಿಂಗಳಿಗೆ {amount} ಕೂಡ ಇದರಲ್ಲಿ ಲೆಕ್ಕ ಹಾಕಲಾಗಿದೆ. ಈ ಮೊತ್ತ ನಮ್ಮ ಅಂದಾಜು. ನಿಜವಾದ ಸಾಲಕ್ಕೆ ಇದಕ್ಕಿಂತ ಹೆಚ್ಚು ಅಥವಾ ಕಡಿಮೆ ಖರ್ಚಾಗಬಹುದು.',
  'ch.householdEstimate': 'ಇದು ನಿಮ್ಮ ಉತ್ತರಗಳಿಂದ ನಾವು ಮಾಡಿದ ಅಂದಾಜು. ಇದು ಯಾವುದೇ ಸಾಲ ಕೊಡುವವರ ತೀರ್ಮಾನವಲ್ಲ.',
  'ch.householdRbiCovered': 'ನೀವು ಹೇಳಿದ ಆದಾಯದ ಪ್ರಕಾರ, ನಿಮ್ಮ ಕುಟುಂಬ ವರ್ಷಕ್ಕೆ {income}-ವರೆಗೆ ಗಳಿಸುತ್ತದೆ. ಇಂಥ ಕುಟುಂಬಗಳಿಗೆ, ಹೊಸ ಸಾಲವನ್ನೂ ಸೇರಿಸಿ ಕುಟುಂಬದ ಎಲ್ಲಾ ಸಾಲಗಳ ಕಂತುಗಳು ಕುಟುಂಬದ ತಿಂಗಳ ಆದಾಯದ {limit}%ಗಿಂತ ಹೆಚ್ಚಾದರೆ, RBI ನಿಯಂತ್ರಿಸುವ ಸಾಲ ಸಂಸ್ಥೆ ಹೊಸ ಮೈಕ್ರೋಫೈನಾನ್ಸ್ ಸಾಲ ಕೊಡುವಂತಿಲ್ಲ ಎಂದು RBI ನಿಯಮಗಳು ಹೇಳುತ್ತವೆ.',
  'ch.householdRbiNotCovered': 'ನೀವು ಹೇಳಿದ ಆದಾಯದ ಪ್ರಕಾರ, ನಿಮ್ಮ ಕುಟುಂಬ ವರ್ಷಕ್ಕೆ {income}-ಗಿಂತ ಹೆಚ್ಚು ಗಳಿಸುತ್ತದೆ. ಮೈಕ್ರೋಫೈನಾನ್ಸ್ ಸಾಲಗಳಿಗೆ RBI ಇಟ್ಟಿರುವ {limit}% ಮಿತಿ ಅಷ್ಟರವರೆಗೆ ಗಳಿಸುವ ಕುಟುಂಬಗಳಿಗೆ ಮಾತ್ರ, ಹಾಗಾಗಿ ನಿಮ್ಮ ಕುಟುಂಬಕ್ಕೆ ಅನ್ವಯಿಸುವುದಿಲ್ಲ. ಬೇರೆ ಸಾಲಗಳಿಗೆ ಪ್ರತಿ ಸಾಲ ಕೊಡುವವರು ತಮ್ಮ ಮಿತಿಯನ್ನು ತಾವೇ ಇಡುತ್ತಾರೆ. ಆದರೂ {limit}% ಗೆರೆಯನ್ನು ಒಂದು ಎಚ್ಚರಿಕೆಯಾಗಿ ತೋರಿಸುತ್ತೇವೆ, ನಿಮ್ಮ ಕುಟುಂಬಕ್ಕೆ ನಿಯಮವಾಗಿ ಅಲ್ಲ.',
