  'ch.coinLabel': 'ಪ್ರತಿ 10 ರೂಪಾಯಿಯಲ್ಲಿ {n} ರೂಪಾಯಿ ನಿಮ್ಮ ಕೈಯಲ್ಲಿ ಉಳಿಯುತ್ತದೆ',
