  'sc.eligUnchecked': 'ಈ ನಿಯಮಗಳನ್ನು ನಿಮ್ಮ ವಿವರಗಳೊಂದಿಗೆ ನಾವು ಹೋಲಿಸಿ ನೋಡಿಲ್ಲ. ಪ್ರತಿಯೊಂದನ್ನೂ ಈ ಯೋಜನೆಯನ್ನು ನಡೆಸುವ ಕಚೇರಿಯಲ್ಲಿ ಪರಿಶೀಲಿಸಿ.',
