  'sch.eyebrow': 'ಸರ್ಕಾರಿ ಸಹಾಯ',
  'sch.title': 'ನಿಮಗೆ ಸಹಾಯ ಆಗಬಹುದಾದ ಯೋಜನೆಗಳು',
  'sch.subtitle': 'ನಿಮ್ಮ ಕೆಲಸದ ಬಗೆ, ನಿಮ್ಮ ರಾಜ್ಯ, ನಿಮ್ಮ ಉದ್ಯಮ ಹಳ್ಳಿಯಲ್ಲಿದೆಯೇ ನಗರದಲ್ಲಿದೆಯೇ ಎಂಬುದರ ಮೇಲೆ ಇವನ್ನು ಆರಿಸಿದ್ದೇವೆ. ಇದು ಪಟ್ಟಿಯಲ್ಲಿ ಏಕೆ ಇದೆ ಮತ್ತು ಅರ್ಜಿ ಹಾಕುವ ಮೊದಲು ಏನು ನೋಡಬೇಕು ಎಂದು ತಿಳಿಯಲು ಒಂದು ಯೋಜನೆ ತೆರೆಯಿರಿ.',
  'sch.finishTitle': 'ಮೊದಲು ನಿಮ್ಮ ವಿವರ ಪೂರ್ಣ ಮಾಡಿ',
  'sch.finishText': 'ಮೊದಲು ನಾಲ್ಕೂ ಹಂತಗಳನ್ನು ಪೂರ್ಣ ಮಾಡಿ, ಆಗ ನಿಮ್ಮ ಕೆಲಸದ ಬಗೆ ಮತ್ತು ರಾಜ್ಯದ ಆಧಾರದ ಮೇಲೆ ಯೋಜನೆಗಳನ್ನು ತೋರಿಸಬಹುದು.',
  'sch.noneTitle': 'ಹೊಂದುವ ಯೋಜನೆ ಸಿಗಲಿಲ್ಲ',
  'sch.noneText': 'ನಾವು ನೋಡುವ ಯೋಜನೆಗಳಲ್ಲಿ ನೀವು ಆಯ್ಕೆ ಮಾಡಿದ ಕೆಲಸ ಬರುವುದಿಲ್ಲ. ಇದು ನಿರಾಕರಣೆ ಅಲ್ಲ — ನಮ್ಮಲ್ಲಿ ಇರುವ ಮಾಹಿತಿಯಿಂದ ಹೊಂದಿಕೆಯನ್ನು ಖಚಿತ ಮಾಡಲು ಆಗಲಿಲ್ಲ ಎಂದಷ್ಟೇ.',
  'sch.noneCovered': 'ನಾವು ನೋಡುವ ಯೋಜನೆಗಳು ಇವುಗಳಿಗೆ ಸಹಾಯ ಮಾಡುತ್ತವೆ: ಅಂಗಡಿ ಮತ್ತು ಕೊಂಡು ಮಾರುವುದು, ವಸ್ತು ತಯಾರಿಕೆ, ಸೇವಾ ಕೆಲಸ, ಆಹಾರ ಪದಾರ್ಥ ತಯಾರಿಕೆ, ಹೊಲಿಗೆ ಕೆಲಸ, ಕರಕುಶಲ ಕೆಲಸ, ಕೃಷಿ, ಹಾಲಿನ ಕೆಲಸ, ಕೋಳಿ ಸಾಕಣೆ, ಜೇನು ಸಾಕಣೆ ಮತ್ತು ಬೀದಿಯಲ್ಲಿ ಮಾರುವುದು. ನಿಮ್ಮ ಕೆಲಸ ಇವುಗಳಲ್ಲಿ ಯಾವುದಕ್ಕಾದರೂ ಹತ್ತಿರವಿದ್ದರೆ, ಹಿಂದೆ ಹೋಗಿ ಅದನ್ನೇ ಆಯ್ಕೆ ಮಾಡಿ.',
  'sch.changeWork': 'ನನ್ನ ಕೆಲಸದ ಬಗೆ ಬದಲಾಯಿಸು',
  'sch.alwaysCheck': 'ಹೊಸ ನಿಯಮಗಳನ್ನು ಯಾವಾಗಲೂ ಸರ್ಕಾರಿ ಕಚೇರಿಯಲ್ಲಿ ಪರಿಶೀಲಿಸಿ.',
  'sch.found': '{n} ಸಹಾಯದ ದಾರಿಗಳು ಸಿಕ್ಕಿವೆ',
  'sch.before': 'ಅರ್ಜಿ ಹಾಕುವ ಮೊದಲು',
  'sch.before1': 'ಪಟ್ಟಿಯಲ್ಲಿ ಇರುವುದು ಎಂದರೆ ಈ ಯೋಜನೆ ನಿಮ್ಮ ಕೆಲಸದ ಬಗೆ ಮತ್ತು ನಿಮ್ಮ ರಾಜ್ಯಕ್ಕೆ ಅನ್ವಯಿಸುತ್ತದೆ ಎಂದು ಮಾತ್ರ. ನೀವು ಅರ್ಹರು ಎಂದಾಗಲೀ ಸರ್ಕಾರ ಒಪ್ಪಿಗೆ ಕೊಟ್ಟಿದೆ ಎಂದಾಗಲೀ ಅರ್ಥವಲ್ಲ.',
