  'lvlnote.other': 'ಇದನ್ನು ಯಾವ ಕಚೇರಿ ನಡೆಸುತ್ತದೆ ಎಂದು ನಿಮ್ಮ ಜಿಲ್ಲಾ ಕಚೇರಿಯಲ್ಲಿ ಕೇಳಿ.',
