  'rp.subtitle': 'ನಿಮ್ಮ ವಿವರ, ಹಣ, ವ್ಯಾಪಾರ, ಊರಿನ ಮಾರುಕಟ್ಟೆ ಮತ್ತು ಮುಂದಿನ ಹೆಜ್ಜೆಗಳ ಸುಲಭ ಸಾರಾಂಶ.',
