  'rp.nextTitle': 'ಮುಂದೆ ನೀವು ಏನು ಮಾಡಬೇಕು',
  'rp.observations': 'ನಾವು ಗಮನಿಸಿದ್ದು',
  'rp.detailedFigures': 'ವಿವರವಾದ ಅಂಕಿಗಳನ್ನು ತೋರಿಸು',
  'rp.noScheme': 'ಈ ಪರಿಶೀಲನೆಯಲ್ಲಿ ಯಾವ ಸರ್ಕಾರಿ ಯೋಜನೆಯೂ ಹೊಂದಿಕೆಯಾಗಲಿಲ್ಲ.',
  'rp.schemeNote': 'ಪಟ್ಟಿಯಲ್ಲಿ ಇದ್ದ ಮಾತ್ರಕ್ಕೆ ನೀವು ಅರ್ಹರು ಎಂದು ಅರ್ಥವಲ್ಲ. ಈಗಿನ ನಿಯಮಗಳು ಮತ್ತು ಅರ್ಜಿ ಹಾಕುವ ವಿಧಾನವನ್ನು ಯಾವಾಗಲೂ ಸರ್ಕಾರಿ ಕಚೇರಿಯಲ್ಲಿ ಪರಿಶೀಲಿಸಿ.',
  'rp.footer': 'ಈ ವರದಿ ಮೊದಲ ಹಂತದ ಮಾರ್ಗದರ್ಶನ ಕೊಡುತ್ತದೆ. ಯೋಜನೆಯ ಅರ್ಹತೆ, ಸಾಲದ ಒಪ್ಪಿಗೆ ಮತ್ತು ಆದಾಯ ಸರ್ಕಾರಿ ನಿಯಮಗಳ ಮತ್ತು ನಿಮ್ಮ ಪರಿಸ್ಥಿತಿಯ ಮೇಲೆ ಅವಲಂಬಿಸಿರುತ್ತದೆ.',
  'rp.keepNote': 'ಈ ವರದಿಯಲ್ಲಿರುವ ಅಂಕಿಗಳು ಮತ್ತು ಸಲಹೆಯನ್ನು ನೀವು ಕಳುಹಿಸಿದ ಉತ್ತರಗಳಿಂದ ಲೆಕ್ಕಹಾಕಲಾಗಿದೆ. ನೀವು {startover} ಎಂಬ ಬಟನ್ ಒತ್ತುವವರೆಗೆ ಈ ಟ್ಯಾಬ್ ನಿಮ್ಮ ಉತ್ತರಗಳನ್ನು ಮತ್ತು ಈ ವರದಿಯನ್ನು ಇಟ್ಟುಕೊಳ್ಳುತ್ತದೆ, ಟ್ಯಾಬ್ ಮುಚ್ಚಿದರೆ ಸಾಮಾನ್ಯವಾಗಿ ಅವು ಅಳಿಸಿಹೋಗುತ್ತವೆ. ಈ ವರದಿಯನ್ನು ಇಟ್ಟುಕೊಳ್ಳಲು, ಈಗಲೇ {button} ಎಂಬ ಬಟನ್ ಒತ್ತಿ ಇದನ್ನು ಮುದ್ರಿಸಿ ಅಥವಾ PDF ಆಗಿ ಉಳಿಸಿ.',
