  'talk.title': 'ಮಾತನಾಡಿ ಅಥವಾ ಬರೆದು ಉತ್ತರಗಳನ್ನು ತುಂಬಿ',
  'talk.optional': 'ಐಚ್ಛಿಕ ಶಾರ್ಟ್‌ಕಟ್',
  'talk.subtitle': 'ನಿಮ್ಮ ವ್ಯವಹಾರ ಏನು, ನಿಮಗೆ ಎಷ್ಟು ಹಣ ಬೇಕು ಮತ್ತು ನೀವು ಎಲ್ಲಿ ವಾಸಿಸುತ್ತೀರಿ ಎಂದು ಕೆಲವು ವಾಕ್ಯಗಳಲ್ಲಿ ಹೇಳಿ. ನಿಮ್ಮ ಮಾತಿನಿಂದ ನಾವು ಉತ್ತರಗಳನ್ನು ಹುಡುಕುತ್ತೇವೆ, ಮತ್ತು ಫಾರ್ಮ್‌ಗೆ ಹಾಕುವ ಮೊದಲು ಪ್ರತಿ ಉತ್ತರವನ್ನು ನೀವೇ ಪರಿಶೀಲಿಸುತ್ತೀರಿ.',
  'talk.entryText': 'ಬರೆಯುವುದಕ್ಕಿಂತ ಮಾತನಾಡಲು ಬಯಸುತ್ತೀರಾ? ನಿಮ್ಮ ಭಾಷೆಯಲ್ಲಿ ಹೇಳಿ, ನಾವು ಫಾರ್ಮ್ ತುಂಬುತ್ತೇವೆ, ನೀವು ಅದನ್ನು ಪರಿಶೀಲಿಸಿ.',
  'talk.sendsTitle': 'ಪ್ರಾರಂಭಿಸುವ ಮೊದಲು',
  'talk.sendsText': 'ನಿಮ್ಮ ಧ್ವನಿ ಮತ್ತು ನಿಮ್ಮ ಮಾತುಗಳನ್ನು Meta ನಡೆಸುವ ಒಂದು AI ಸೇವೆಗೆ ಕಳುಹಿಸಲಾಗುತ್ತದೆ. ಅದು ನಿಮ್ಮ ಮಾತುಗಳನ್ನು ಬರೆದು, ಅವುಗಳಿಂದ ನಿಮ್ಮ ಉತ್ತರಗಳನ್ನು ಹುಡುಕುತ್ತದೆ. ನಾವು ಅವುಗಳನ್ನು ಉಳಿಸಿಕೊಳ್ಳುವುದಿಲ್ಲ. Meta ಅವುಗಳನ್ನು ತನ್ನ ಸ್ವಂತ ನಿಯಮಗಳ ಪ್ರಕಾರ ನಿರ್ವಹಿಸುತ್ತದೆ. ಈ ಸೇವೆ ಉಚಿತ ಕ್ರೆಡಿಟ್ ಮೇಲೆ ನಡೆಯುತ್ತಿದ್ದರೆ, Meta ಅವುಗಳನ್ನು ತನ್ನ ಉತ್ಪನ್ನಗಳನ್ನು ಸುಧಾರಿಸಲು ಕೂಡ ಬಳಸಬಹುದು. ದಯವಿಟ್ಟು ನಿಮ್ಮ ಹೆಸರು, ಫೋನ್ ಸಂಖ್ಯೆ ಅಥವಾ ಬ್ಯಾಂಕ್ ವಿವರಗಳನ್ನು ಹೇಳಬೇಡಿ.',
  'talk.rulesNote': 'AI ಕೇಳಿ ನಿಮ್ಮ ಉತ್ತರಗಳನ್ನು ಹುಡುಕುತ್ತದೆ ಅಷ್ಟೇ. ಫಲಿತಾಂಶ, ಯೋಜನೆಗಳು ಮತ್ತು ಸಲಹೆ ನೀವೇ ಉತ್ತರಗಳನ್ನು ಬರೆದಾಗ ಹೇಗೋ ಹಾಗೆಯೇ, ಮೊದಲೇ ನಿಗದಿಯಾದ ನಿಯಮಗಳಿಂದಲೇ ಬರುತ್ತವೆ.',
  'talk.consent': 'ಈ ಪುಟದಲ್ಲಿ ನಾನು ಹೇಳುವ ಅಥವಾ ಬರೆಯುವುದನ್ನು Meta ನಡೆಸುವ AI ಸೇವೆಗೆ ಕಳುಹಿಸಲು ನಾನು ಒಪ್ಪುತ್ತೇನೆ.',
  'talk.consentRequired': 'ಮುಂದುವರಿಯುವ ಮೊದಲು ದಯವಿಟ್ಟು ಒಪ್ಪಿಗೆಯ ಪೆಟ್ಟಿಗೆಯಲ್ಲಿ ಟಿಕ್ ಮಾಡಿ.',
