  'talk.notUsed': 'ಬಳಸಿಲ್ಲ: ಇದು ಫಾರ್ಮ್‌ನಲ್ಲಿರುವ ಆಯ್ಕೆಗಳಲ್ಲಿ ಒಂದಲ್ಲ.',
