  'talk.noneFound': 'ಇದರಲ್ಲಿ ನಮಗೆ ಯಾವ ಉತ್ತರವೂ ಸಿಗಲಿಲ್ಲ. ನೀವು ಯಾವ ಕೆಲಸ ಮಾಡುತ್ತೀರಿ, ನಿಮಗೆ ಎಷ್ಟು ಹಣ ಬೇಕು, ತಿಂಗಳಿಗೆ ಎಷ್ಟು ಗಳಿಸುತ್ತೀರಿ ಮತ್ತು ಖರ್ಚು ಮಾಡುತ್ತೀರಿ, ಎಲ್ಲಿ ವಾಸಿಸುತ್ತೀರಿ ಎಂದು ಹೇಳಿ.',
  'talk.apply': 'ಈ ಉತ್ತರಗಳನ್ನು ಬಳಸಿ',
  'talk.applyNote': 'ನಿಮ್ಮ ಹೆಸರು ಮತ್ತು ವ್ಯವಹಾರದ ಹೆಸರನ್ನು ತುಂಬಿಲ್ಲ: ಅವುಗಳನ್ನು ನೀವೇ ಬರೆಯಿರಿ. ಮುಂದಿನ ಪುಟಗಳಲ್ಲಿ ನೀವು ಪ್ರತಿ ಉತ್ತರವನ್ನು ಬದಲಾಯಿಸಬಹುದು.',
