  'ch.householdRbiCovered': 'तुम्ही सांगितलेल्या उत्पन्नानुसार तुमचे कुटुंब वर्षाला {income} पर्यंत कमावते. अशा कुटुंबांसाठी RBI चे नियम सांगतात की नवीन कर्ज धरून कुटुंबाच्या सर्व कर्जांचे हप्ते कुटुंबाच्या महिन्याच्या उत्पन्नाच्या {limit}% पेक्षा जास्त होत असतील, तर RBI च्या नियंत्रणाखालील कर्ज देणारी संस्था नवीन मायक्रोफायनान्स कर्ज देऊ शकत नाही.',
  'ch.householdRbiNotCovered': 'तुम्ही सांगितलेल्या उत्पन्नानुसार तुमचे कुटुंब वर्षाला {income} पेक्षा जास्त कमावते. मायक्रोफायनान्स कर्जांसाठीची RBI ची {limit}% मर्यादा फक्त तेवढ्यापर्यंत कमावणाऱ्या कुटुंबांना लागू होते, म्हणून तुमच्या कुटुंबाला लागू होत नाही. इतर कर्जांसाठी प्रत्येक कर्ज देणारा आपली मर्यादा स्वतः ठरवतो. तरीही आम्ही {limit}% ची रेषा एक धोक्याची सूचना म्हणून दाखवतो, तुमच्या कुटुंबासाठी नियम म्हणून नाही.',
