  'rp.footer': 'हा अहवाल सुरुवातीचे मार्गदर्शन देतो. योजनेची पात्रता, कर्जाची मंजुरी आणि कमाई सरकारी नियमांवर आणि तुमच्या परिस्थितीवर अवलंबून असते.',
  'rp.keepNote': 'या अहवालातील आकडे आणि सल्ला तुम्ही पाठवलेल्या उत्तरांवरून काढले आहेत. तुम्ही {startover} हे बटण दाबेपर्यंत हा टॅब तुमची उत्तरे आणि हा अहवाल ठेवतो, आणि टॅब बंद केल्यावर ते सहसा पुसले जातात. हा अहवाल ठेवायचा असेल, तर आत्ताच {button} हे बटण दाबा आणि तो प्रिंट करा किंवा PDF म्हणून सेव्ह करा.',
