  'rp.keepNote': 'এই রিপোর্টের হিসাব আর পরামর্শ আপনার পাঠানো উত্তর থেকে তৈরি। আপনি {startover} বোতামটি না টেপা পর্যন্ত এই ট্যাব আপনার উত্তর আর এই রিপোর্ট রাখে, আর ট্যাব বন্ধ করলে সাধারণত সেগুলো মুছে যায়। এই রিপোর্টটি রাখতে চাইলে, এখনই {button} বোতামটি টিপে এটি প্রিন্ট করুন বা PDF হিসেবে সেভ করুন।',
