  'privacy.fiduciarySite': '{fiduciary}-এর ওয়েবসাইট',
  'privacy.sentTitle': 'কী পাঠানো হয়',
  'privacy.sentLead': 'শেষ ধাপে {button} বোতামটি টিপলে শুধু এই উত্তরগুলো পাঠানো হয়:',
  'privacy.sentConsent': 'সেগুলোর সঙ্গে আপনার সম্মতির একটি তথ্যও যায়: এই বিজ্ঞপ্তির সংস্করণ, আপনি যে ভাষায় পড়ছিলেন, সময়, আর আপনাকে বয়সের কথা জিজ্ঞেস করা হলে আপনার উত্তর।',
  'privacy.localTitle': 'কী শুধু এই ডিভাইসেই থাকে',
  'privacy.localText': 'এগুলো কখনও পাঠানো হয় না: আপনার নাম, আপনার ব্যবসার নাম, আপনার গ্রাম বা শহর, আপনি কোথায় বিক্রি করেন, আর আপনার ক্রেতা কারা। এগুলো এই ব্রাউজার ট্যাবেই থাকে আর আপনার রিপোর্টে ছাপা হয়। {startover} বোতামটি টিপলে এগুলো মুছে যায়, আর ট্যাব বন্ধ করলেও সাধারণত মুছে যায়। আপনার উপভাষাও কখনও পাঠানো হয় না। পরের বারের জন্য এই ব্রাউজার আপনার উপভাষা, লেখার আকার আর রং মনে রাখে। এটি আপনার ভাষাও মনে রাখে, যা আপনার সম্মতির সঙ্গে পাঠানো হয়।',
  'privacy.whyTitle': 'কেন',
  'privacy.whyText': 'আপনার ফলাফল হিসাব করার জন্য আপনার উত্তর পাঠানো হয়: হিসাব মেলে কি না, কোন প্রকল্প আর কোন স্থানীয় তথ্য দেখাতে হবে, আর এরপর কী করতে হবে। নিচে যেমন বলা আছে, আপনার উত্তর থেকে তৈরি একটি কোডও এই যাচাইয়ের রেকর্ড হিসেবে রাখা হয়।',
  'privacy.keptTitle': 'কী রাখা হয়',
  'privacy.keptText': 'এই সফটওয়্যার আপনার পাঠানো উত্তর সেভ করে না। প্রতিটি যাচাইয়ের জন্য এটি একটি রেকর্ড লেখে: সময়, আপনার সম্মতির তথ্য, আপনার উত্তর থেকে তৈরি একটি কোড, আর যাচাই ঠিকমতো হয়েছে কি না এমন কারিগরি তথ্য। একই উত্তর থেকে একই কোড তৈরি হয়, কিন্তু সেই রেকর্ডে আপনার উত্তর থাকে না। কোনো উত্তর বাদ পড়ায় বা ভুল থাকায় যাচাই করা না গেলে, সেই রেকর্ডে শুধু সময় আর সেই কারিগরি তথ্য থাকে।',
  'privacy.keptDays': '{fiduciary} এই রেকর্ডগুলো {days} দিন রাখে।',
  'privacy.keptAsk': 'এই রেকর্ডগুলো কতদিন রাখা হয় তা জানতে এখানে জিজ্ঞেস করুন: {contact}',
  'privacy.keptUnknown': 'এই রেকর্ডগুলো কতদিন রাখা হয়, এই সংস্করণে তা বলা নেই।',
  'privacy.hostLogs': 'এই পরিষেবা চালানো কম্পিউটারগুলোও নিজেদের রেকর্ড রাখতে পারে, যেমন আপনার ডিভাইসের ইন্টারনেট ঠিকানা। বেশিরভাগ ওয়েবসাইটই এমন করে।',
  'privacy.choicesTitle': 'আপনার পছন্দ',
  'privacy.choiceStop': 'আপনাকে এগোতেই হবে এমন নয়। সম্মতির বাক্সে টিক দিয়ে {button} বোতামটি না টেপা পর্যন্ত কিছুই পাঠানো হয় না।',
  'privacy.choiceStartOver': 'এই ট্যাব থেকে আপনার উত্তর মুছতে ওপরের {startover} বোতামটি টিপুন। আগেই যা পাঠানো হয়েছে, তার ওপর এর কোনো প্রভাব নেই।',
  'privacy.choiceRights': 'আপনার সম্মতি ফিরিয়ে নিতে, অথবা যা পাঠানো হয়েছে তা দেখতে, সংশোধন করাতে বা মুছে ফেলতে বলার জন্য, অথবা অভিযোগ জানাতে এখানে যোগাযোগ করুন: {contact}',
  'privacy.choiceNoContact': 'আপনার সম্মতি ফিরিয়ে নিতে, অথবা যা পাঠানো হয়েছে তা দেখতে, সংশোধন করাতে বা মুছে ফেলতে এই সংস্করণে কোনো যোগাযোগের তথ্য দেওয়া হয়নি। যে ব্যক্তি বা সংস্থা আপনাকে এই লিংক দিয়েছে, তাদের জিজ্ঞেস করুন।',
  'privacy.grievanceLink': 'অভিযোগ জানাতে: {fiduciary}',
  'privacy.board': '13 মে 2027 থেকে, আপনার অভিযোগের উত্তরে সন্তুষ্ট না হলে, আপনি ভারতের ডেটা সুরক্ষা বোর্ডেও (Data Protection Board of India) অভিযোগ করতে পারেন।',
  'privacy.age': 'শুধু 18 বছর বা তার বেশি বয়সের মানুষ নিজে এটি ব্যবহার করতে পারেন। এর চেয়ে কম বয়সী কারও সঙ্গে রাজি থাকা মা-বাবা বা অভিভাবক থাকতে হবে।',
