  'talk.title': 'বলে বা লিখে উত্তর ভরুন',
  'talk.optional': 'ঐচ্ছিক শর্টকাট',
  'talk.subtitle': 'কয়েকটি বাক্যে বলুন আপনার কাজ কী, আপনার কত টাকা দরকার এবং আপনি কোথায় থাকেন। আমরা আপনার কথা থেকে উত্তর খুঁজি, আর ফর্মে বসানোর আগে প্রতিটি উত্তর আপনি নিজে যাচাই করেন।',
  'talk.entryText': 'লেখার চেয়ে বলতে চান? নিজের ভাষায় বলুন, আমরা ফর্ম ভরে দেব আর আপনি তা যাচাই করবেন।',
  'talk.sendsTitle': 'শুরু করার আগে',
  'talk.sendsText': 'আপনার কণ্ঠস্বর ও আপনার কথা Meta-র চালানো একটি AI পরিষেবায় পাঠানো হয়। সেটি আপনার কথা লিখে নেয় এবং তার মধ্যে থেকে আপনার উত্তর খুঁজে বের করে। আমরা এগুলো জমা রাখি না। Meta এগুলো তাদের নিজস্ব নিয়ম অনুযায়ী সামলায়। এই পরিষেবা বিনামূল্যের ক্রেডিটে চললে, Meta এগুলো তাদের পণ্য উন্নত করতেও ব্যবহার করতে পারে। অনুগ্রহ করে আপনার নাম, ফোন নম্বর বা ব্যাংকের তথ্য বলবেন না।',
  'talk.rulesNote': 'AI শুধু শোনে আর আপনার উত্তর খোঁজে। ফলাফল, প্রকল্প ও পরামর্শ আগের মতোই নির্দিষ্ট নিয়মে বের হয়, যেমন আপনি নিজে উত্তর লিখলে হয়।',
  'talk.consent': 'আমি সম্মত যে এই পাতায় আমি যা বলব বা লিখব তা Meta-র চালানো AI পরিষেবায় পাঠানো হবে।',
  'talk.consentRequired': 'এগিয়ে যাওয়ার আগে অনুগ্রহ করে সম্মতির বাক্সে টিক দিন।',
