  'talk.textHint': 'বলার বদলে আপনি এখানে লিখতেও পারেন। কোনো শব্দ ভুল শোনা হলে এগিয়ে যাওয়ার আগে এখানেই ঠিক করে নিন।',
  'talk.tooLong': 'এটি খুব বড়। অনুগ্রহ করে {max} অক্ষরের মধ্যে রাখুন।',
